	this.hookFrame = type;
	this.hookKind = component;
	var kind = 0;
	var seen = 0;
	var extra = 0;
	var current = type;
	var sibling = component;
	var token = component;
	if (current == null) {
		kind = 1;
		seen = 0;
		extra = 0;
		this.hookCursor = 1;
		this.hookListRef = 0;
	} else if (typeof current == 'function') {
		kind = 2;
		seen = 1;
